#!/usr/bin/env python3
"""Render an offline 2D film of the actual 3D study for HTML panels without WebGL."""
from pathlib import Path
from playwright.sync_api import sync_playwright
import json,hashlib
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'build/checks/character3d';HTML=ROOT/'visual-preview/maziss-3d-study.html';N=28
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--enable-unsafe-swiftshader'])
 page=browser.new_page(viewport={'width':1200,'height':1000},offline=True);page.set_content(HTML.read_text());page.wait_for_function('window.maziss3d&&maziss3d.ready',timeout=30000)
 page.evaluate('''()=>{const a=maziss3d;a.setPhase(0);a.renderer.setSize(480,600,false);a.renderer.setPixelRatio(1);a.camera.aspect=480/600;a.camera.updateProjectionMatrix();}''')
 views=[]
 for angle in range(0,360,45):
  page.evaluate('a=>maziss3d.setView(a)',angle);frames=[]
  for frame in range(N):
   data=page.evaluate('p=>{maziss3d.setPhase(p);return maziss3d.renderer.domElement.toDataURL("image/webp",.84)}',frame/N);frames.append(data)
  page.evaluate('maziss3d.setWalking(false)');idle=page.evaluate('maziss3d.renderer.domElement.toDataURL("image/webp",.84)')
  page.click('#anatomy');body=page.evaluate('maziss3d.renderer.domElement.toDataURL("image/webp",.84)');page.click('#dressed');page.evaluate('maziss3d.setWalking(true)')
  views.append({'angle':angle,'frames':frames,'idle':idle,'body':body});print('Rendered',angle,'degrees',flush=True)
 cycle=page.evaluate('maziss3d.data.motion.cycleSeconds');browser.close()
payload=json.dumps({'views':views,'cycle':cycle},separators=(',',':'))
review='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Maziss 3D rendered study</title><style>body{font:16px system-ui;background:#252d35;color:#eee8dc;margin:0}main{max-width:1050px;margin:auto;padding:24px}p{line-height:1.5}button,select{font:inherit;color:#fff;background:#46535d;border:1px solid #71828d;border-radius:5px;padding:9px;margin:4px}nav{display:flex;flex-wrap:wrap}img{display:block;width:min(100%,480px);height:auto;background:radial-gradient(ellipse,#767c7c,#3e4650);border-radius:8px;margin:18px auto}a{color:#a8ddff}</style><main><h1>Maziss: rendered 3D construction study</h1><p>Actual renders from the complete model. The face, clothes and surface finish are preliminary; this study tests geometry and perspective. These images play without WebGL, an internet connection or AI service.</p><p><a href="maziss-3d-study.html">Open the live model to inspect any angle and individual parts</a></p><nav id="views"></nav><nav><button id="play">Pause</button><button id="step">Next frame</button><label>View <select id="mode"><option value="frames">Walking</option><option value="idle">Standing</option><option value="body">Body beneath clothes</option></select></label><label>Playback <select id="rate"><option value="1">Normal</option><option value=".5">Half speed</option><option value=".25">Quarter speed</option></select></label></nav><img id="frame" width="480" height="600" alt="Rendered complete 3D character"><p id="status"></p><p>Eight camera angles, 28 frames per walking cycle, plus complete standing and underlying-body views. The jacket and trousers are continuous geometry; the head, eyes, mouth and bag use the shared skeleton. Camera depth determines overlap. Some intersections, simplified hands and facial forms remain. The approved painted cartoon finish remains the target for a later art pass.</p></main><script>const FILM=__FILM__;let view=0,phase=0,mode='frames',playing=true,rate=1,last=null;const image=document.getElementById('frame');function draw(){const a=FILM.views[view];image.src=mode==='frames'?a.frames[Math.floor(phase*a.frames.length)%a.frames.length]:a[mode];document.getElementById('status').textContent=a.angle+'° · '+(mode==='frames'?'Frame '+(Math.floor(phase*a.frames.length)+1)+' / '+a.frames.length:mode==='idle'?'Standing':'Body beneath clothes');}for(let i=0;i<FILM.views.length;i++){const b=document.createElement('button');b.textContent=FILM.views[i].angle+'°';b.onclick=()=>{view=i;draw()};document.getElementById('views').append(b)}document.getElementById('play').onclick=()=>{playing=!playing;document.getElementById('play').textContent=playing?'Pause':'Play'};document.getElementById('mode').onchange=e=>{mode=e.target.value;draw()};document.getElementById('rate').onchange=e=>rate=+e.target.value;document.getElementById('step').onclick=()=>{playing=false;phase=(phase+1/28)%1;document.getElementById('play').textContent='Play';draw()};function tick(t){if(last!==null&&playing&&mode==='frames'){phase=(phase+Math.min(.08,(t-last)/1000)*rate/FILM.cycle)%1;draw()}last=t;requestAnimationFrame(tick)}draw();requestAnimationFrame(tick);window.maziss3dFilm={ready:true,getState:()=>({view,phase,mode,playing})};</script></html>'''.replace('__FILM__',payload)
target=ROOT/'visual-preview/maziss-3d-rendered.html';target.write_text(review);target.chmod(0o644)
(OUT/'rendered-manifest.json').write_text(json.dumps({'source_html_sha256':hashlib.sha256(HTML.read_bytes()).hexdigest(),'frames':N*len(views),'angles':len(views),'output_sha256':hashlib.sha256(target.read_bytes()).hexdigest(),'bytes':target.stat().st_size},indent=2)+'\n');print('Created',target.name,target.stat().st_size,'bytes')
